const sheet=document.querySelector('#sheet'),formulaInput=document.querySelector('#formulaInput'),nameBox=document.querySelector('#nameBox');
const saveStatus=document.querySelector('#saveStatus'),toast=document.querySelector('#toast'),stats=document.querySelector('#selectionStats');
const STORE='myexcel2026-workbook-v2';let rows=30,cols=12,active=null,saveTimer,activeSheet=0,historyReady=false;
const SNAPSHOTS='myexcel2026-snapshots-v1';
let cells={},sheets=[{name:'Лист1',rows,cols,cells}],selectedIds=new Set(['A1']);
let undoStack=[],redoStack=[],copiedStyle=null,namedRanges={};

const colName=n=>{let s='';while(n>=0){s=String.fromCharCode(n%26+65)+s;n=Math.floor(n/26)-1}return s};
const cellId=(r,c)=>colName(c)+(r+1);
function buildSheet(){sheet.innerHTML='';sheet.classList.toggle('freeze-first-row',!!sheets[activeSheet]?.freezeFirstRow);sheet.classList.toggle('freeze-first-col',!!sheets[activeSheet]?.freezeFirstCol);sheet.classList.toggle('protected',!!sheets[activeSheet]?.protected);const protectBtn=document.querySelector('#protectBtn');if(protectBtn)protectBtn.textContent=sheets[activeSheet]?.protected?'🔓 Снять защиту':'🔒 Защита';sheet.style.gridTemplateColumns=`44px repeat(${cols},var(--cell-width,105px))`;sheet.append(make('div','corner',''));
  for(let c=0;c<cols;c++){const head=make('div','column-head',colName(c));head.onclick=()=>selectColumn(c);sheet.append(head)}
  for(let r=0;r<rows;r++){const rowHead=make('div','row-head',r+1);rowHead.onclick=()=>selectRow(r);if(sheets[activeSheet]?.freezeRow===r)rowHead.classList.add('frozen-row-head');sheet.append(rowHead);for(let c=0;c<cols;c++){const id=cellId(r,c),el=make('div','cell','');if(r===0)el.classList.add('first-data-row');if(sheets[activeSheet]?.freezeRow===r)el.classList.add('frozen-data-row');el.contentEditable=sheets[activeSheet]?.protected?'false':'true';el.dataset.id=id;applyCell(el,id);applyMerge(el,id);el.addEventListener('mousedown',e=>{if(e.shiftKey){e.preventDefault();selectRangeTo(id)}});el.addEventListener('click',()=>toggleCheckbox(id));el.addEventListener('dblclick',()=>openCellAction(id));el.addEventListener('focus',()=>selectCell(el));el.addEventListener('beforeinput',e=>{if(sheets[activeSheet]?.protected)return e.preventDefault();if(!el.dataset.historyCaptured){captureHistory();el.dataset.historyCaptured='1'}});el.addEventListener('input',()=>{setCellFromElement(el);queueSave()});el.addEventListener('keydown',handleKeys);el.addEventListener('blur',()=>renderValues());sheet.append(el)}}applyFilter();applySelection()
}
function make(tag,className,text){const el=document.createElement(tag);el.className=className;el.textContent=text;return el}
function getData(id){return cells[id]||(cells[id]={value:'',style:{}})}
function applyCell(el,id){const data=getData(id);el.textContent=data.type==='checkbox'?(data.checked?'☑':'☐'):data.value;el.classList.toggle('checkbox-cell',data.type==='checkbox');el.classList.toggle('has-note',!!data.note);el.classList.toggle('has-validation',!!data.validation?.length);el.classList.toggle('has-link',!!data.link);el.title=[data.note,data.validation?.length?'Список: '+data.validation.join(', '):'',data.link||''].filter(Boolean).join('\n');Object.assign(el.style,data.style||{})}
function openCellAction(id){const data=getData(id);if(data.link){window.open(data.link,'_blank','noopener');return}chooseValidation(id)}
function applyMerge(el,id){const data=getData(id);if(data.mergeParent){el.classList.add('merge-hidden');return}if(data.merge){el.classList.add('merged-cell');el.style.width=`calc(var(--cell-width,105px) * ${data.merge.cols})`;el.style.height=`${30*data.merge.rows}px`}}
function chooseValidation(id){const data=getData(id);if(!data.validation?.length||sheets[activeSheet]?.protected)return;const answer=prompt('Выберите значение:\n'+data.validation.map((v,i)=>`${i+1}. ${v}`).join('\n'),data.value||data.validation[0]);if(answer===null)return;const index=Number(answer)-1,value=data.validation.includes(answer)?answer:data.validation[index];if(value===undefined)return showToast('Выберите пункт из списка');captureHistory();data.value=value;buildSheet();renderValues();queueSave()}
function toggleCheckbox(id){const data=getData(id);if(data.type!=='checkbox'||sheets[activeSheet]?.protected)return;captureHistory();data.checked=!data.checked;data.value=data.checked?'TRUE':'FALSE';buildSheet();renderValues();queueSave()}
function setCellFromElement(el){const data=getData(el.dataset.id);data.value=el.textContent;formulaInput.value=data.value;updateStats()}
function selectCell(el){document.querySelector('.cell.selected')?.classList.remove('selected');active=el;selectedIds=new Set([el.dataset.id]);el.dataset.historyCaptured='';el.classList.add('selected');applySelection();nameBox.textContent=el.dataset.id;formulaInput.value=getData(el.dataset.id).value;updateStats()}
function cellPosition(id){const m=id.match(/([A-Z]+)(\d+)/);return{r:+m[2]-1,c:lettersToNumber(m[1])}}
function selectRangeTo(id){const start=cellPosition(active?.dataset.id||'A1'),end=cellPosition(id);selectedIds=new Set();for(let r=Math.min(start.r,end.r);r<=Math.max(start.r,end.r);r++)for(let c=Math.min(start.c,end.c);c<=Math.max(start.c,end.c);c++)selectedIds.add(cellId(r,c));applySelection();nameBox.textContent=`${active?.dataset.id||'A1'}:${id}`;updateStats()}
function selectRow(r){selectedIds=new Set();for(let c=0;c<cols;c++)selectedIds.add(cellId(r,c));active=document.querySelector(`[data-id="${cellId(r,0)}"]`);applySelection();nameBox.textContent=`Строка ${r+1}`;updateStats()}
function selectColumn(c){selectedIds=new Set();for(let r=0;r<rows;r++)selectedIds.add(cellId(r,c));active=document.querySelector(`[data-id="${cellId(0,c)}"]`);applySelection();nameBox.textContent=`Столбец ${colName(c)}`;updateStats()}
function applySelection(){document.querySelectorAll('.cell').forEach(el=>el.classList.toggle('range-selected',selectedIds.has(el.dataset.id)&&el!==active))}
function handleKeys(e){const arrows={ArrowUp:[-1,0],ArrowDown:[1,0],ArrowLeft:[0,-1],ArrowRight:[0,1]};if(e.key==='Enter'){e.preventDefault();move(1,0)}else if(e.key==='Tab'){e.preventDefault();move(0,e.shiftKey?-1:1)}else if(arrows[e.key]){e.preventDefault();move(...arrows[e.key])}}
function move(dr,dc){if(!active)return;const match=active.dataset.id.match(/([A-Z]+)(\d+)/);const c=lettersToNumber(match[1]),r=+match[2]-1;document.querySelector(`[data-id="${cellId(Math.max(0,Math.min(rows-1,r+dr)),Math.max(0,Math.min(cols-1,c+dc)))}"]`)?.focus()}
function lettersToNumber(s){let n=0;for(const ch of s)n=n*26+ch.charCodeAt(0)-64;return n-1}

formulaInput.addEventListener('focus',()=>formulaInput.dataset.historyCaptured='');formulaInput.addEventListener('beforeinput',()=>{if(active&&!formulaInput.dataset.historyCaptured){captureHistory();formulaInput.dataset.historyCaptured='1'}});formulaInput.addEventListener('input',()=>{if(!active)return;getData(active.dataset.id).value=formulaInput.value;active.textContent=formulaInput.value;queueSave()});
formulaInput.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();renderValues();active?.focus()}});
function valueOf(id,stack=[]){return valueOfAt(activeSheet,id,stack)}
function valueOfAt(sheetIndex,id,stack=[]){const key=`${sheetIndex}:${id}`;if(stack.includes(key))return '#ЦИКЛ!';const raw=(sheets[sheetIndex]?.cells?.[id]?.value||'').trim();if(!raw.startsWith('='))return raw;try{return calculate(raw.slice(1),[...stack,key],sheetIndex)}catch{return '#ОШИБКА!'}}
function calculate(expression,stack,sheetIndex=activeSheet){let exp=expression.toUpperCase();Object.entries(namedRanges).forEach(([name,range])=>{if(range.sheetIndex===sheetIndex)exp=exp.replace(new RegExp(`\\b${name}\\b`,'g'),`${range.start}:${range.end}`)});exp=exp.replace(/(?:'([^']+)'|([А-ЯЁA-Z0-9_]+))!([A-Z]+\d+)/g,(_,quoted,plain,id)=>{const name=quoted||plain,index=sheets.findIndex(s=>s.name.toUpperCase()===name);const v=parseFloat(valueOfAt(index,id,stack));return Number.isFinite(v)?v:0});exp=exp.replace(/(SUM|AVERAGE|MIN|MAX|COUNT|MEDIAN)\(([A-Z]+\d+):([A-Z]+\d+)\)/g,(_,fn,start,end)=>{const v=rangeValues(start,end,stack,sheetIndex);if(fn==='COUNT')return v.length;if(!v.length)return'0';if(fn==='SUM')return v.reduce((a,b)=>a+b,0);if(fn==='AVERAGE')return v.reduce((a,b)=>a+b,0)/v.length;if(fn==='MIN')return Math.min(...v);if(fn==='MAX')return Math.max(...v);const s=[...v].sort((a,b)=>a-b),m=Math.floor(s.length/2);return s.length%2?s[m]:(s[m-1]+s[m])/2});exp=exp.replace(/IF\(([^,;]+)[,;]([^,;]+)[,;]([^\)]+)\)/g,'(($1)?($2):($3))');exp=exp.replace(/[A-Z]+\d+/g,id=>{const val=parseFloat(valueOfAt(sheetIndex,id,stack));return Number.isFinite(val)?val:0});exp=exp.replace(/ABS\(([^()]+)\)/g,'Math.abs($1)').replace(/SQRT\(([^()]+)\)/g,'Math.sqrt($1)').replace(/POWER\(([^,;]+)[,;]([^\)]+)\)/g,'Math.pow($1,$2)').replace(/ROUND\(([^,;]+)[,;](\d+)\)/g,'(Math.round(($1)*10**$2)/10**$2)');if(!/^[\d+\-*/().,<>=!?:\sA-Za-z]+$/.test(exp)||/[^Mathabspowqrtund\d+\-*/().,<>=!?:\s]/i.test(exp.replace(/Math\.(abs|sqrt|pow|round)/g,'')))throw Error();exp=exp.replace(/([^<>!=])=([^=])/g,'$1==$2');return Function(`"use strict";return (${exp})`)()}
function rangeValues(start,end,stack,sheetIndex=activeSheet){const a=start.match(/([A-Z]+)(\d+)/),b=end.match(/([A-Z]+)(\d+)/);const out=[];for(let r=+a[2]-1;r<=+b[2]-1;r++)for(let c=lettersToNumber(a[1]);c<=lettersToNumber(b[1]);c++){const n=parseFloat(valueOfAt(sheetIndex,cellId(r,c),stack));if(Number.isFinite(n))out.push(n)}return out}
function renderValues(){document.querySelectorAll('.cell').forEach(el=>{if(el===active&&document.activeElement===el)return;const data=getData(el.dataset.id);if(data.type==='checkbox'){el.textContent=data.checked?'☑':'☐';el.classList.remove('formula-error');return}let value=valueOf(el.dataset.id);el.classList.toggle('formula-error',String(value).startsWith('#'));if(data.style?.format==='currency'&&value!==''&&!isNaN(value))value=Number(value).toLocaleString('ru-RU')+' ₸';if(data.style?.format==='percent'&&value!==''&&!isNaN(value))value=Number(value).toLocaleString('ru-RU')+'%';if(data.style?.format==='number'&&value!==''&&!isNaN(value))value=Number(value).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2});if(data.style?.format==='date'&&/^\d{4}-\d{2}-\d{2}$/.test(value)){const [y,m,d]=value.split('-');value=`${d}.${m}.${y}`}el.textContent=value})}
function format(prop,value){if(!active)return;captureHistory();selectedIds.forEach(id=>getData(id).style[prop]=value);document.querySelectorAll('.cell').forEach(el=>{if(selectedIds.has(el.dataset.id))el.style[prop]=value});queueSave()}
document.querySelectorAll('[data-format]').forEach(btn=>btn.onclick=()=>{const p=btn.dataset.format==='bold'?'fontWeight':btn.dataset.format==='italic'?'fontStyle':'textDecoration';const v=p==='fontWeight'?(active?.style[p]==='bold'?'normal':'bold'):p==='fontStyle'?(active?.style[p]==='italic'?'normal':'italic'):(active?.style[p]==='underline'?'none':'underline');format(p,v)});
document.querySelectorAll('[data-align]').forEach(btn=>btn.onclick=()=>format('textAlign',btn.dataset.align));
document.querySelector('#fontName').onchange=e=>format('fontFamily',e.target.value);document.querySelector('#fontSize').onchange=e=>format('fontSize',e.target.value+'px');document.querySelector('#textColor').oninput=e=>format('color',e.target.value);document.querySelector('#fillColor').oninput=e=>format('backgroundColor',e.target.value);
document.querySelector('#currencyBtn').onclick=()=>setNumberFormat('currency');document.querySelector('#percentBtn').onclick=()=>setNumberFormat('percent');document.querySelector('#numberBtn').onclick=()=>setNumberFormat('number');document.querySelector('#dateBtn').onclick=()=>setNumberFormat('date');document.querySelector('#borderBtn').onclick=()=>{if(!active)return;captureHistory();const on=getData([...selectedIds][0]).style.border==='1px solid #667085';selectedIds.forEach(id=>getData(id).style.border=on?'':'1px solid #667085');buildSheet();renderValues();queueSave()};
function setNumberFormat(type){if(!active)return;captureHistory();selectedIds.forEach(id=>getData(id).style.format=type);renderValues();queueSave()}
function quickFormula(fn){if(!selectedIds.size)return showToast('Выделите диапазон');const points=[...selectedIds].map(cellPosition),r1=Math.min(...points.map(p=>p.r)),r2=Math.max(...points.map(p=>p.r)),c1=Math.min(...points.map(p=>p.c)),c2=Math.max(...points.map(p=>p.c)),target=r2>r1?cellId(r2+1,c1):cellId(r1,c2+1);captureHistory();rows=Math.max(rows,r2+2);cols=Math.max(cols,c2+2);getData(target).value=`=${fn}(${cellId(r1,c1)}:${cellId(r2,c2)})`;selectedIds=new Set([target]);buildSheet();renderValues();queueSave();document.querySelector(`[data-id="${target}"]`)?.focus();showToast('Формула добавлена')}
document.querySelector('#quickSumBtn').onclick=()=>quickFormula('SUM');document.querySelector('#quickAvgBtn').onclick=()=>quickFormula('AVERAGE');document.querySelector('#quickMinBtn').onclick=()=>quickFormula('MIN');document.querySelector('#quickMaxBtn').onclick=()=>quickFormula('MAX');
document.querySelector('#namedRangeBtn').onclick=()=>{if(!selectedIds.size)return;const name=(prompt('Название латинскими буквами, например SALES:')||'').trim().toUpperCase();if(!/^[A-Z_][A-Z0-9_]*$/.test(name)||/^[A-Z]+\d+$/.test(name))return name&&showToast('Используйте латинские буквы, цифры и знак _');const points=[...selectedIds].map(cellPosition),start=cellId(Math.min(...points.map(p=>p.r)),Math.min(...points.map(p=>p.c))),end=cellId(Math.max(...points.map(p=>p.r)),Math.max(...points.map(p=>p.c)));captureHistory();namedRanges[name]={sheetIndex:activeSheet,start,end};queueSave();showToast(`Диапазон ${name} = ${start}:${end}. Пример: =SUM(${name})`)};
document.querySelector('#traceFormulaBtn').onclick=()=>{document.querySelectorAll('.formula-trace').forEach(el=>el.classList.remove('formula-trace'));if(!active)return;const id=active.dataset.id,raw=String(getData(id).value||''),refs=[...raw.toUpperCase().matchAll(/\b([A-Z]+\d+)\b/g)].map(m=>m[1]),dependents=Object.entries(cells).filter(([,d])=>String(d.value||'').toUpperCase().match(new RegExp(`\\b${id}\\b`))).map(([cell])=>cell),all=[...new Set([...refs,...dependents])];all.forEach(cell=>document.querySelector(`[data-id="${cell}"]`)?.classList.add('formula-trace'));if(!all.length)return showToast('Связи формулы не найдены');showToast(`Связанных ячеек: ${all.length}`);setTimeout(()=>document.querySelectorAll('.formula-trace').forEach(el=>el.classList.remove('formula-trace')),5000)};
document.querySelector('#addRowBtn').onclick=()=>{captureHistory();rows++;buildSheet();renderValues();queueSave()};document.querySelector('#addColBtn').onclick=()=>{captureHistory();cols++;buildSheet();renderValues();queueSave()};
document.querySelector('#insertRowBtn').onclick=()=>{if(!active||sheets[activeSheet]?.protected)return;captureHistory();const at=cellPosition(active.dataset.id).r,next={};Object.entries(cells).forEach(([id,data])=>{const p=cellPosition(id);next[cellId(p.r>=at?p.r+1:p.r,p.c)]=data});cells=next;rows++;selectedIds=new Set([cellId(at,0)]);buildSheet();renderValues();queueSave();showToast(`Строка добавлена перед ${at+1}`)};
document.querySelector('#insertColBtn').onclick=()=>{if(!active||sheets[activeSheet]?.protected)return;captureHistory();const at=cellPosition(active.dataset.id).c,next={};Object.entries(cells).forEach(([id,data])=>{const p=cellPosition(id);next[cellId(p.r,p.c>=at?p.c+1:p.c)]=data});cells=next;cols++;selectedIds=new Set([cellId(0,at)]);buildSheet();renderValues();queueSave();showToast(`Столбец ${colName(at)} добавлен`)};
document.querySelector('#deleteRowBtn').onclick=()=>{if(rows<=1)return;captureHistory();rows--;Object.keys(cells).forEach(id=>{const m=id.match(/\d+/);if(+m[0]>rows)delete cells[id]});buildSheet();renderValues();queueSave()};
document.querySelector('#deleteColBtn').onclick=()=>{if(cols<=1)return;captureHistory();cols--;Object.keys(cells).forEach(id=>{if(lettersToNumber(id.match(/[A-Z]+/)[0])>=cols)delete cells[id]});buildSheet();renderValues();queueSave()};
document.querySelector('#clearBtn').onclick=()=>{if(!active)return;captureHistory();getData(active.dataset.id).value='';active.textContent='';formulaInput.value='';queueSave();updateStats()};
function updateStats(){const ids=selectedIds.size>1?[...selectedIds]:Object.keys(cells),nums=ids.map(id=>parseFloat(valueOf(id))).filter(Number.isFinite);const sum=nums.reduce((a,b)=>a+b,0),avg=nums.length?sum/nums.length:0,min=nums.length?Math.min(...nums):0,max=nums.length?Math.max(...nums):0;stats.textContent=`Сумма: ${round(sum)} · Среднее: ${round(avg)} · Мин: ${round(min)} · Макс: ${round(max)} · Чисел: ${nums.length}`}
const round=n=>Math.round(n*100)/100;
function workbookSnapshot(){syncSheet();return JSON.stringify({sheets,activeSheet,namedRanges})}
function captureHistory(){if(!historyReady)return;undoStack.push(workbookSnapshot());if(undoStack.length>40)undoStack.shift();redoStack=[]}
function restoreSnapshot(raw){const d=JSON.parse(raw);sheets=d.sheets;namedRanges=d.namedRanges||namedRanges;activeSheet=Math.min(d.activeSheet,sheets.length-1);({rows,cols,cells}=sheets[activeSheet]);buildSheet();renderTabs();renderValues();queueSave()}
function undo(){if(!undoStack.length)return showToast('Больше нечего отменять');redoStack.push(workbookSnapshot());restoreSnapshot(undoStack.pop());showToast('Действие отменено')}
function redo(){if(!redoStack.length)return showToast('Больше нечего повторять');undoStack.push(workbookSnapshot());restoreSnapshot(redoStack.pop());showToast('Действие повторено')}
document.querySelector('#undoBtn').onclick=undo;document.querySelector('#redoBtn').onclick=redo;
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='f'){e.preventDefault();openFind()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommands()}else if(e.key==='Escape')document.querySelectorAll('.modal').forEach(m=>m.classList.add('hidden'))});
function syncSheet(){sheets[activeSheet]={...sheets[activeSheet],rows,cols,cells}}
function queueSave(){saveStatus.textContent='Сохранение…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>{syncSheet();localStorage.setItem(STORE,JSON.stringify({version:11,sheets,activeSheet,namedRanges}));maybeAutoSnapshot();saveStatus.textContent='Книга сохранена'},450)}
function download(content,name,type){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
document.querySelector('#saveBtn').onclick=()=>{syncSheet();download(JSON.stringify({app:'MyExcel 2026',version:11,sheets,namedRanges},null,2),'MyExcel-книга.json','application/json')};
document.querySelector('#csvBtn').onclick=()=>{const lines=[];for(let r=0;r<rows;r++){const line=[];for(let c=0;c<cols;c++)line.push('"'+String(valueOf(cellId(r,c))).replaceAll('"','""')+'"');lines.push(line.join(','))}download('\ufeff'+lines.join('\n'),'MyExcel-таблица.csv','text/csv;charset=utf-8')};
document.querySelector('#xlsBtn').onclick=()=>{if(!window.XLSX)return showToast('Модуль Excel ещё загружается — повторите через несколько секунд');syncSheet();const workbook=XLSX.utils.book_new();sheets.forEach((item,index)=>{const data=[];for(let r=0;r<item.rows;r++){const row=[];for(let c=0;c<item.cols;c++){const raw=item.cells?.[cellId(r,c)]?.value??'';row.push(raw)}data.push(row)}const worksheet=XLSX.utils.aoa_to_sheet(data);XLSX.utils.book_append_sheet(workbook,worksheet,(item.name||`Лист${index+1}`).slice(0,31))});XLSX.writeFile(workbook,'MyExcel-книга.xlsx');showToast('Книга XLSX сохранена')};
function escapeHtml(v){return String(v).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function workbookReportHtml(){syncSheet();const sections=sheets.map((s,si)=>{let table='<table>';for(let r=0;r<s.rows;r++){table+='<tr>';for(let c=0;c<s.cols;c++){const tag=r===0?'th':'td';table+=`<${tag}>${escapeHtml(valueOfAt(si,cellId(r,c)))}</${tag}>`}table+='</tr>'}return `<section><h2>${escapeHtml(s.name)}</h2>${table}</section>`}).join('');return `<!doctype html><html lang="ru"><head><meta charset="UTF-8"><title>MyExcel — отчёт</title><style>body{font:14px Arial;margin:28px;color:#1f2937}h1{color:#107c41}section{margin:28px 0;overflow:auto;break-after:page}table{border-collapse:collapse}th,td{border:1px solid #cbd5e1;padding:7px 10px;min-width:80px}th{background:#107c41;color:white}@media print{section:last-child{break-after:auto}}</style></head><body><h1>MyExcel 2026 — отчёт</h1>${sections}</body></html>`}
document.querySelector('#htmlReportBtn').onclick=()=>download('\ufeff'+workbookReportHtml(),'MyExcel-отчёт.html','text/html;charset=utf-8');
document.querySelector('#printWorkbookBtn').onclick=()=>{const w=window.open('','_blank');if(!w)return showToast('Разрешите всплывающие окна');w.document.write(workbookReportHtml());w.document.close();w.onload=()=>w.print()};
