document.querySelector('#openBtn').onclick=()=>document.querySelector('#fileInput').click();document.querySelector('#fileInput').onchange=e=>{const file=e.target.files[0];if(!file)return;const lower=file.name.toLowerCase(),reader=new FileReader();reader.onload=()=>{try{if(lower.endsWith('.xlsx')||lower.endsWith('.xls')){if(!window.XLSX)throw Error('XLSX module');const workbook=XLSX.read(reader.result,{type:'array',cellFormula:true});sheets=workbook.SheetNames.map(name=>{const ws=workbook.Sheets[name],range=ws['!ref']?XLSX.utils.decode_range(ws['!ref']):{s:{r:0,c:0},e:{r:29,c:11}},sheetCells={};for(let r=range.s.r;r<=range.e.r;r++)for(let c=range.s.c;c<=range.e.c;c++){const source=ws[XLSX.utils.encode_cell({r,c})];if(source)sheetCells[cellId(r,c)]={value:source.f?'='+source.f:String(source.v??''),style:{}}}return{name,rows:Math.max(30,range.e.r+1),cols:Math.max(12,range.e.c+1),cells:sheetCells}});namedRanges={};activeSheet=0;({rows,cols,cells}=sheets[0])}else if(lower.endsWith('.json')){const d=JSON.parse(reader.result);sheets=Array.isArray(d.sheets)?d.sheets:[{name:'Лист1',rows:d.rows||30,cols:d.cols||12,cells:d.cells||{}}];namedRanges=d.namedRanges||{};activeSheet=0;({rows,cols,cells}=sheets[0])}else{cells={};namedRanges={};const lines=reader.result.replace(/^\ufeff/,'').split(/\r?\n/);rows=Math.max(30,lines.length);cols=12;lines.forEach((line,r)=>line.split(',').forEach((v,c)=>{cols=Math.max(cols,c+1);getData(cellId(r,c)).value=v.replace(/^"|"$/g,'').replaceAll('""','"')}));sheets=[{name:'Лист1',rows,cols,cells}];activeSheet=0}buildSheet();renderTabs();renderValues();queueSave();updateStats();showToast('Книга открыта')}catch{showToast('Не удалось открыть файл. Проверьте его формат')}};if(lower.endsWith('.xlsx')||lower.endsWith('.xls'))reader.readAsArrayBuffer(file);else reader.readAsText(file);e.target.value=''};
