function sortSheet(direction){if(!active)return showToast('Сначала выберите ячейку в нужном столбце');captureHistory();const column=lettersToNumber(active.dataset.id.match(/[A-Z]+/)[0]),matrix=[];for(let r=0;r<rows;r++){const row=[];for(let c=0;c<cols;c++)row.push(JSON.parse(JSON.stringify(cells[cellId(r,c)]||{value:'',style:{}})));matrix.push(row)}matrix.sort((a,b)=>{const av=a[column].value,bv=b[column].value,an=Number(av),bn=Number(bv),result=Number.isFinite(an)&&Number.isFinite(bn)?an-bn:String(av).localeCompare(String(bv),'ru',{numeric:true});return direction==='asc'?result:-result});cells={};matrix.forEach((row,r)=>row.forEach((data,c)=>{if(data.value||Object.keys(data.style||{}).length)cells[cellId(r,c)]=data}));buildSheet();renderValues();queueSave();showToast(direction==='asc'?'Отсортировано по возрастанию':'Отсортировано по убыванию')}
