document.querySelector('#dedupeBtn').onclick=()=>{if(!active)return showToast('Выберите столбец');const column=cellPosition(active.dataset.id).c,seen=new Set(),keep=[0];for(let r=1;r<rows;r++){const value=String(valueOf(cellId(r,column))).trim().toLowerCase();if(!value||!seen.has(value)){keep.push(r);if(value)seen.add(value)}}const removed=rows-keep.length;if(!removed)return showToast('Дубликаты не найдены');if(!confirm(`Удалить повторяющиеся строки: ${removed}?`))return;captureHistory();const next={};keep.forEach((oldR,newR)=>{for(let c=0;c<cols;c++){const data=cells[cellId(oldR,c)];if(data)next[cellId(newR,c)]=data}});cells=next;rows=keep.length;buildSheet();renderValues();queueSave();showToast(`Удалено строк: ${removed}`)};
