document.querySelector('#validationBtn').onclick=()=>{if(!selectedIds.size||sheets[activeSheet]?.protected)return showToast('Выберите ячейки и снимите защиту');const answer=prompt('Введите варианты списка через запятую:');if(answer===null)return;const options=[...new Set(answer.split(',').map(v=>v.trim()).filter(Boolean))];if(!options.length)return showToast('Добавьте хотя бы один вариант');captureHistory();selectedIds.forEach(id=>getData(id).validation=options);buildSheet();renderValues();queueSave();showToast('Выпадающий список добавлен — двойное нажатие для выбора')};
const statsModal=document.querySelector('#statsModal');document.querySelector('#bookStatsBtn').onclick=()=>{syncSheet();let filled=0,formulas=0,comments=0,errors=0;sheets.forEach((s,si)=>Object.entries(s.cells||{}).forEach(([id,d])=>{if(d.value!==''||d.type==='checkbox')filled++;if(String(d.value||'').startsWith('='))formulas++;if(d.note)comments++;if(String(valueOfAt(si,id)).startsWith('#'))errors++}));const cards=[['Листов',sheets.length],['Заполнено ячеек',filled],['Формул',formulas],['Комментариев',comments],['Ошибок формул',errors],['Активный лист',sheets[activeSheet].name]];document.querySelector('#bookStatsGrid').innerHTML=cards.map(([label,value])=>`<div><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`).join('');statsModal.classList.remove('hidden')};document.querySelector('#closeStatsBtn').onclick=()=>statsModal.classList.add('hidden');statsModal.onclick=e=>{if(e.target===statsModal)statsModal.classList.add('hidden')};
