function matches(){const q=document.querySelector('#findText').value.toLowerCase();if(!q)return[];const indexes=document.querySelector('#searchWorkbook').checked?sheets.map((_,i)=>i):[activeSheet],out=[];indexes.forEach(si=>Object.keys(sheets[si].cells||{}).filter(id=>String(sheets[si].cells[id].value).toLowerCase().includes(q)).sort().forEach(id=>out.push({si,id})));return out}
function findNext(){const list=matches();if(!list.length){document.querySelector('#findResult').textContent='Ничего не найдено';return}findCursor=(findCursor+1)%list.length;const item=list[findCursor];if(item.si!==activeSheet)switchSheet(item.si);findModal.classList.add('hidden');setTimeout(()=>document.querySelector(`[data-id="${item.id}"]`)?.focus(),20);document.querySelector('#findResult').textContent=`Найдено: ${list.length} · ${sheets[item.si].name}!${item.id}`}
document.querySelector('#findNextBtn').onclick=findNext;document.querySelector('#replaceBtn').onclick=()=>{const list=matches();if(!list.length)return showToast('Ничего не найдено');captureHistory();const item=list[Math.max(0,findCursor)%list.length],q=document.querySelector('#findText').value,repl=document.querySelector('#replaceText').value,d=sheets[item.si].cells[item.id];d.value=String(d.value).replace(q,repl);if(item.si!==activeSheet)switchSheet(item.si);buildSheet();renderValues();queueSave();showToast('Значение заменено')};document.querySelector('#replaceAllBtn').onclick=()=>{const list=matches();if(!list.length)return showToast('Ничего не найдено');captureHistory();const q=document.querySelector('#findText').value,repl=document.querySelector('#replaceText').value;list.forEach(item=>{const d=sheets[item.si].cells[item.id];d.value=String(d.value).split(q).join(repl)});({rows,cols,cells}=sheets[activeSheet]);buildSheet();renderValues();queueSave();document.querySelector('#findResult').textContent=`Заменено: ${list.length}`};
const noteModal=document.querySelector('#noteModal');function openNote(){if(!active)return showToast('Выберите ячейку');const id=active.dataset.id;document.querySelector('#noteCellName').textContent=`Ячейка ${id}`;document.querySelector('#noteText').value=getData(id).note||'';noteModal.dataset.cell=id;noteModal.classList.remove('hidden');setTimeout(()=>document.querySelector('#noteText').focus(),30)}document.querySelector('#noteBtn').onclick=openNote;document.querySelector('#closeNoteBtn').onclick=()=>noteModal.classList.add('hidden');noteModal.onclick=e=>{if(e.target===noteModal)noteModal.classList.add('hidden')};document.querySelector('#saveNoteBtn').onclick=()=>{if(sheets[activeSheet]?.protected)return showToast('Сначала снимите защиту листа');captureHistory();getData(noteModal.dataset.cell).note=document.querySelector('#noteText').value.trim();noteModal.classList.add('hidden');buildSheet();renderValues();queueSave();showToast('Комментарий сохранён')};document.querySelector('#deleteNoteBtn').onclick=()=>{if(sheets[activeSheet]?.protected)return showToast('Сначала снимите защиту листа');captureHistory();getData(noteModal.dataset.cell).note='';noteModal.classList.add('hidden');buildSheet();renderValues();queueSave();showToast('Комментарий удалён')};
const templatesModal=document.querySelector('#templatesModal');document.querySelector('#templatesBtn').onclick=()=>templatesModal.classList.remove('hidden');document.querySelector('#closeTemplatesBtn').onclick=()=>templatesModal.classList.add('hidden');templatesModal.onclick=e=>{if(e.target===templatesModal)templatesModal.classList.add('hidden')};document.querySelectorAll('[data-template]').forEach(btn=>btn.onclick=()=>applyTemplate(btn.dataset.template));
function put(r,c,value,style={}){cells[cellId(r,c)]={value:String(value),style}}
function applyTemplate(type){if(Object.values(cells).some(d=>d.value)&&!confirm('Заменить содержимое текущего листа шаблоном?'))return;captureHistory();cells={};rows=30;cols=12;const head={fontWeight:'bold',backgroundColor:'#107c41',color:'#ffffff',textAlign:'center'};if(type==='budget'){sheets[activeSheet].name='Месячный бюджет';['Дата','Категория','Доход, ₸','Расход, ₸','Комментарий'].forEach((v,c)=>put(0,c,v,head));put(0,6,'Доходы',head);put(1,6,'Расходы',head);put(2,6,'Остаток',head);put(0,7,'=SUM(C2:C30)',{format:'currency',fontWeight:'bold'});put(1,7,'=SUM(D2:D30)',{format:'currency'});put(2,7,'=H1-H2',{format:'currency',fontWeight:'bold'})}else if(type==='portfolio'){sheets[activeSheet].name='Портфель акций';['Тикер','Компания','Цена покупки','Количество','Вложено, ₸','Текущая цена','Стоимость, ₸','Результат, ₸'].forEach((v,c)=>put(0,c,v,head));for(let r=1;r<15;r++){put(r,4,`=C${r+1}*D${r+1}`,{format:'currency'});put(r,6,`=F${r+1}*D${r+1}`,{format:'currency'});put(r,7,`=G${r+1}-E${r+1}`,{format:'currency'})}}else{sheets[activeSheet].name='Мясо разбор';['Дата','Приход','Брутто, кг','Чистый выход, кг','Отход, кг','Выход, %','Комментарий'].forEach((v,c)=>put(0,c,v,head));for(let r=1;r<20;r++)put(r,5,`=D${r+1}/C${r+1}*100`,{format:'percent'})}templatesModal.classList.add('hidden');selectedIds=new Set(['A1']);syncSheet();buildSheet();renderTabs();renderValues();queueSave();showToast('Шаблон создан')}
function drawChart(){const m=document.querySelector('#chartRange').value.toUpperCase().replace(/\s/g,'').match(/^([A-Z]+\d+):([A-Z]+\d+)$/);if(!m)return showToast('Укажите диапазон, например A1:B6');const a=m[1].match(/([A-Z]+)(\d+)/),b=m[2].match(/([A-Z]+)(\d+)/),r1=Math.min(+a[2],+b[2])-1,r2=Math.max(+a[2],+b[2])-1,c1=Math.min(lettersToNumber(a[1]),lettersToNumber(b[1])),c2=Math.max(lettersToNumber(a[1]),lettersToNumber(b[1]));if(c2-c1<1)return showToast('Нужно минимум два столбца');const labels=[],values=[];for(let r=r1;r<=r2;r++){labels.push(String(valueOf(cellId(r,c1)))||`Строка ${r+1}`);values.push(Number(valueOf(cellId(r,c1+1)))||0)}paintChart(labels,values,document.querySelector('#chartType').value)}
function paintChart(labels,values,type){const canvas=document.querySelector('#chartCanvas'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,p=45,colors=['#107c41','#4f8cff','#f59e0b','#e05260','#8b5cf6','#14b8a6','#ec4899'],max=Math.max(...values.map(Math.abs),1);ctx.clearRect(0,0,w,h);ctx.fillStyle=getComputedStyle(document.body).getPropertyValue('--surface');ctx.fillRect(0,0,w,h);ctx.font='13px Segoe UI';ctx.textAlign='center';if(type==='pie'){const total=values.reduce((a,b)=>a+Math.max(0,b),0)||1;let angle=-Math.PI/2;values.forEach((v,i)=>{const next=angle+Math.max(0,v)/total*Math.PI*2;ctx.beginPath();ctx.moveTo(w/2,h/2);ctx.arc(w/2,h/2,Math.min(w,h)*.38,angle,next);ctx.fillStyle=colors[i%colors.length];ctx.fill();angle=next})}else{ctx.strokeStyle='#94a3b8';ctx.beginPath();ctx.moveTo(p,p);ctx.lineTo(p,h-p);ctx.lineTo(w-p,h-p);ctx.stroke();const gap=(w-p*2)/Math.max(values.length,1);if(type==='line'){ctx.strokeStyle=colors[0];ctx.lineWidth=3;ctx.beginPath();values.forEach((v,i)=>{const x=p+gap*(i+.5),y=h-p-(v/max)*(h-p*2);i?ctx.lineTo(x,y):ctx.moveTo(x,y);ctx.fillStyle=colors[0];ctx.fillRect(x-4,y-4,8,8)});ctx.stroke()}else values.forEach((v,i)=>{const bh=(v/max)*(h-p*2),x=p+gap*i+gap*.18;ctx.fillStyle=colors[i%colors.length];ctx.fillRect(x,h-p-bh,gap*.64,bh)});ctx.fillStyle='#64748b';labels.forEach((l,i)=>ctx.fillText(l.slice(0,10),p+gap*(i+.5),h-18))}document.querySelector('#chartLegend').innerHTML=labels.map((l,i)=>`<span><i style="background:${colors[i%colors.length]}"></i>${String(l).replace(/[&<>]/g,'')}: ${round(values[i])}</span>`).join('')}
function loadSnapshots(){try{return JSON.parse(localStorage.getItem(SNAPSHOTS)||'[]')}catch{return[]}}
function createSnapshot(manual=false){syncSheet();const list=loadSnapshots();list.unshift({time:new Date().toISOString(),data:JSON.stringify({sheets,activeSheet,namedRanges})});try{localStorage.setItem(SNAPSHOTS,JSON.stringify(list.slice(0,6)));localStorage.setItem(SNAPSHOTS+'-last',String(Date.now()));if(manual){renderSnapshots();showToast('Снимок книги создан')}}catch{if(manual)showToast('Недостаточно места для снимка')}}
function maybeAutoSnapshot(){const last=Number(localStorage.getItem(SNAPSHOTS+'-last')||0);if(Date.now()-last>300000)createSnapshot(false)}
const snapshotsModal=document.querySelector('#snapshotsModal');function renderSnapshots(){const list=loadSnapshots(),box=document.querySelector('#snapshotList');box.innerHTML=list.length?list.map((s,i)=>`<div class="snapshot-item"><div><b>Версия ${i+1}</b><br><small>${escapeHtml(new Date(s.time).toLocaleString('ru-RU'))}</small></div><button data-restore-snapshot="${i}">Восстановить</button></div>`).join(''):'<p class="chart-help">Снимков пока нет.</p>';box.querySelectorAll('[data-restore-snapshot]').forEach(btn=>btn.onclick=()=>{if(!confirm('Восстановить эту версию книги?'))return;const saved=JSON.parse(loadSnapshots()[Number(btn.dataset.restoreSnapshot)].data);sheets=saved.sheets;namedRanges=saved.namedRanges||{};activeSheet=Math.min(saved.activeSheet||0,sheets.length-1);({rows,cols,cells}=sheets[activeSheet]);buildSheet();renderTabs();renderValues();queueSave();snapshotsModal.classList.add('hidden');showToast('Версия восстановлена')})}
document.querySelector('#snapshotsBtn').onclick=()=>{renderSnapshots();snapshotsModal.classList.remove('hidden')};document.querySelector('#closeSnapshotsBtn').onclick=()=>snapshotsModal.classList.add('hidden');document.querySelector('#createSnapshotBtn').onclick=()=>createSnapshot(true);snapshotsModal.onclick=e=>{if(e.target===snapshotsModal)snapshotsModal.classList.add('hidden')};
const commandModal=document.querySelector('#commandModal'),commandSearch=document.querySelector('#commandSearch');const commands=[['Найти и заменить','findBtn','Ctrl+F'],['Быстрая сумма','quickSumBtn','SUM'],['Среднее значение','quickAvgBtn','AVERAGE'],['Создать диаграмму','chartBtn',''],['Именованный диапазон','namedRangeBtn',''],['Проверить связи формулы','traceFormulaBtn',''],['Добавить ссылку','linkBtn',''],['Транспонировать таблицу','transposeBtn',''],['Экспорт диапазона CSV','selectionCsvBtn',''],['Статистика книги','bookStatsBtn',''],['Резервные версии','snapshotsBtn',''],['Тёмная тема','themeBtn','']];function renderCommands(){const q=commandSearch.value.toLowerCase(),list=commands.filter(c=>c[0].toLowerCase().includes(q));document.querySelector('#commandList').innerHTML=list.map(c=>`<button data-command-id="${c[1]}"><span>${c[0]}</span><small>${c[2]}</small></button>`).join('');document.querySelectorAll('[data-command-id]').forEach(btn=>btn.onclick=()=>{commandModal.classList.add('hidden');document.querySelector('#'+btn.dataset.commandId)?.click()})}function openCommands(){commandSearch.value='';renderCommands();commandModal.classList.remove('hidden');setTimeout(()=>commandSearch.focus(),20)}document.querySelector('#commandBtn').onclick=openCommands;commandSearch.oninput=renderCommands;commandSearch.onkeydown=e=>{if(e.key==='Enter')document.querySelector('#commandList button')?.click()};commandModal.onclick=e=>{if(e.target===commandModal)commandModal.classList.add('hidden')};
function closeMacMenus(){document.querySelectorAll('.dropdown-menu,.mac-menu-button').forEach(el=>el.classList.remove('open'))}
document.querySelectorAll('.mac-menu-button[data-menu]').forEach(btn=>btn.onclick=e=>{e.stopPropagation();const panel=document.querySelector(`[data-menu-panel="${btn.dataset.menu}"]`),opening=!panel.classList.contains('open');closeMacMenus();if(opening){btn.classList.add('open');panel.classList.add('open')}});
document.querySelectorAll('.dropdown-menu').forEach(menu=>menu.onclick=e=>e.stopPropagation());document.querySelectorAll('.dropdown-menu button').forEach(btn=>btn.addEventListener('click',()=>setTimeout(closeMacMenus,0)));document.addEventListener('click',closeMacMenus);
function switchRibbon(name){document.querySelectorAll('[data-ribbon-tab]').forEach(btn=>btn.classList.toggle('active',btn.dataset.ribbonTab===name));document.querySelectorAll('[data-ribbon]').forEach(pane=>pane.classList.toggle('active',pane.dataset.ribbon===name));document.querySelector('#ribbonHost').classList.remove('collapsed')}
document.querySelectorAll('[data-ribbon-tab]').forEach(btn=>btn.onclick=()=>switchRibbon(btn.dataset.ribbonTab));document.querySelectorAll('[data-ribbon-open]').forEach(btn=>btn.onclick=()=>{switchRibbon(btn.dataset.ribbonOpen);closeMacMenus()});
document.querySelectorAll('[data-trigger]').forEach(btn=>btn.onclick=()=>{closeMacMenus();document.querySelector('#'+btn.dataset.trigger)?.click()});
