document.querySelectorAll('[data-action]').forEach(btn=>btn.onclick=()=>{const action=btn.dataset.action;if(action==='toggle-ribbon')document.querySelector('#ribbonHost').classList.toggle('collapsed');if(action==='toggle-formula')document.querySelector('.formula-bar').classList.toggle('collapsed');if(action==='toggle-grid')sheet.classList.toggle('grid-hidden');closeMacMenus()});
document.querySelector('#helpSearch').onkeydown=e=>{if(e.key==='Enter'){closeMacMenus();openCommands();commandSearch.value=e.currentTarget.value;renderCommands()}};
function restore(){try{const d=JSON.parse(localStorage.getItem(STORE)||localStorage.getItem('myexcel2026-workbook'));if(d){sheets=Array.isArray(d.sheets)?d.sheets:[{name:'Лист1',rows:d.rows||30,cols:d.cols||12,cells:d.cells||{}}];namedRanges=d.namedRanges||{};activeSheet=Math.min(d.activeSheet||0,sheets.length-1);({rows,cols,cells}=sheets[activeSheet])}}catch{}if(localStorage.getItem('myexcel-theme')==='dark')document.body.classList.add('dark');buildSheet();renderTabs();renderValues();updateStats();document.querySelector('[data-id="A1"]').focus();historyReady=true}
